  "it.f_mon_h": "साल के बाद 1 April से रिटर्न प्रोसेस होने के दिन तक। 4 = 31 July तक भरा रिटर्न।",
  "it.m_senior": "60 या ज़्यादा उम्र के रेज़िडेंट जिनकी कोई बिज़नेस या प्रोफ़ेशनल इनकम नहीं, एडवांस टैक्स नहीं भरते (सेक्शन 403(3))। बाकी रकम रिटर्न भरते समय दें।",
