  "it.m_pres": "प्रिज़म्प्टिव स्कीम में पूरा एडवांस टैक्स 15 March को या उससे पहले भरा जाता है (सेक्शन 408(2))।",
  "it.m_sur": "आपकी इनकम ₹50 लाख से ऊपर है: सरचार्ज लिखें, यह यहाँ नहीं निकाला जाता।",
  "it.m_past": "यह साल खत्म हो चुका है। 31 March के बाद भरा एडवांस टैक्स इस साल के एडवांस टैक्स में नहीं गिना जाता; नीचे का ब्याज बताता है कि कमी कितनी महँगी पड़ती है।",
