  "it.print": "प्रिंट",
  "it.basis": "ये आँकड़े किस आधार पर हैं ({d} के अनुसार)",
  "it.b1": "रेट ({d} के अनुसार), टैक्स साल 2026-27: नया रिजीम ₹4 लाख तक शून्य, ₹8 लाख तक 5%, ₹12 लाख तक 10%, ₹16 लाख तक 15%, ₹20 लाख तक 20%, ₹24 लाख तक 25%, उससे ऊपर 30%; रिबेट ऐसी कि ₹12 लाख तक की इनकम पर कोई टैक्स नहीं, थोड़ा ऊपर मार्जिनल रिलीफ़; सैलरी पर स्टैंडर्ड डिडक्शन ₹75,000। पुराना रिजीम: ₹2.5 लाख तक शून्य (60 पर ₹3 लाख, 80 पर ₹5 लाख), ₹5 लाख तक 5%, ₹10 लाख तक 20%, उससे ऊपर 30%; ₹5 लाख तक रिबेट ₹12,500; स्टैंडर्ड डिडक्शन ₹50,000। ये वही रेट हैं जो सैलरी स्लिप टूल पहले से इस्तेमाल करता है; इस बिल्ड में Finance Act से दोबारा नहीं पढ़े गए, इसलिए जाँच लें।",
  "it.b2": "एडवांस टैक्स (Income-tax Act 2025, सेक्शन 403 से 408): जब TDS के बाद टैक्स ₹10,000 या ज़्यादा हो; 15 June तक 15%, 15 September तक 45%, 15 December तक 75%, 15 March तक पूरा; प्रिज़म्प्टिव टैक्सपेयर सब 15 March तक भरता है; 31 March तक का पेमेंट उसी साल में गिना जाता है; 60 या ज़्यादा उम्र के रेज़िडेंट जिनकी बिज़नेस इनकम नहीं, छूट में हैं।",
  "it.b3": "ब्याज: सेक्शन 424 (पुराना 234B) कमी पर हर महीने या महीने के हिस्से का 1% है, जब टैक्स का 90% से कम भरा गया हो; सेक्शन 425 (पुराना 234C) पहली तीन किस्तों में से हर एक की कमी पर 3% है (15 June तक 12% और 15 September तक 36% भरा हो तो नहीं) और March की कमी पर 1%।",
  "it.b4": "ऊपर के सेक्शन Act की एक थर्ड-पार्टी कॉपी (eztax.in) से पढ़े गए, क्योंकि Income Tax Department के अपने पेज ऑटोमैटिक रीडर को मना करते हैं। पुराने सेक्शन 234B और 234C से मिलान और 3% रेट की अवधि वहाँ छपी नहीं है। छपा हुआ Act ही आखिरी है।",
  "it.b5": "किताबों का मुनाफ़ा टैक्सेबल मुनाफ़ा नहीं होता: Act के तहत डेप्रिसिएशन, नामंज़ूर खर्चे और प्रिज़म्प्टिव नियम इसे बदल देते हैं। यह प्लान और डेटा शीट अपने अकाउंटेंट को दें।",
  "it.b6": "ये नहीं निकाले जाते: सरचार्ज, खास रेट वाले कैपिटल गेन, विदेशी टैक्स राहत, नाबालिग की इनकम पर टैक्स, और देर से रिटर्न भरने का ब्याज।",
  "it.b7": "कुछ भी फ़ाइल नहीं होता और आपकी किताबों में कुछ पोस्ट नहीं होता।",
  "it.itr_h": "कुछ सवालों के जवाब दें और देखें कौन-सा रिटर्न फ़ॉर्म सही है, क्यों, और कौन-से कागज़ तैयार रखें।",
  "it.use_form": "सही ITR फ़ॉर्म: {f}",
  "it.q_who": "रिटर्न कौन भर रहा है",
