  "it.formd_ITR-1": "सैलरी या पेंशन, दो तक मकान और ब्याज जैसे दूसरे स्रोत वाले रेज़िडेंट व्यक्ति के लिए, जिसकी कुल इनकम ₹50 लाख तक हो।",
  "it.formd_ITR-2": "ऐसे व्यक्ति या HUF के लिए जिनकी बिज़नेस या प्रोफ़ेशन इनकम नहीं, पर कैपिटल गेन हैं, ₹50 लाख से ऊपर इनकम है, दो से ज़्यादा मकान हैं, विदेशी संपत्ति या इनकम है, या जो ITR-1 में नहीं आते।",
  "it.formd_ITR-3": "ऐसे व्यक्ति या HUF के लिए जिनकी बिज़नेस या प्रोफ़ेशन इनकम प्रिज़म्प्टिव स्कीम में नहीं है, किसी फ़र्म में पार्टनर, या जो ITR-4 में नहीं आते।",
  "it.formd_ITR-4": "प्रिज़म्प्टिव बिज़नेस इनकम वाले रेज़िडेंट व्यक्ति या HUF के लिए, कुल इनकम ₹50 लाख तक, सैलरी या पेंशन, दो तक मकान और दूसरे स्रोत।",
  "it.formd_ITR-5": "फ़र्म, LLP, एसोसिएशन ऑफ़ पर्सन्स और बॉडी ऑफ़ इंडिविजुअल्स के लिए।",
  "it.formd_ITR-6": "कंपनियों के लिए, उनको छोड़कर जो धर्मार्थ या धार्मिक कामों की छूट माँगती हैं।",
  "it.formd_ITR-7": "ट्रस्ट, संस्थाओं, राजनीतिक पार्टियों और ऐसे लोगों के लिए।",
  "it.w_company": "कंपनी ITR-6 भरती है।",
  "it.w_firm": "फ़र्म, LLP या एसोसिएशन ITR-5 भरते हैं।",
  "it.w_other": "ट्रस्ट, संस्थाएँ और राजनीतिक पार्टियाँ ITR-7 भरती हैं।",
  "it.w_partner": "जिस फ़र्म में आप पार्टनर हैं उससे मिली सैलरी या ब्याज बिज़नेस इनकम है, जो ITR-3 में दिखाई जाती है।",
  "it.w_business": "आप बिज़नेस या प्रोफ़ेशनल मुनाफ़ा किताबों से निकालते हैं, इसके लिए ITR-3 चाहिए।",
  "it.w_presnot": "प्रिज़म्प्टिव फ़ॉर्म व्यक्तियों और HUF के लिए है।",
  "it.w_nonres": "जो रेज़िडेंट नहीं है वह ITR-1 या ITR-4 इस्तेमाल नहीं कर सकता।",
  "it.w_over50": "₹50 लाख से ऊपर की कुल इनकम पर ITR-1 और ITR-4 नहीं चलते।",
  "it.w_capgain": "लिस्टेड शेयर की छोटी सीमा के अलावा कैपिटल गेन हों तो ITR-2 या ITR-3 चाहिए।",
  "it.w_houses": "दो से ज़्यादा मकान हों तो ITR-1 और ITR-4 नहीं चलते।",
  "it.w_foreign": "विदेशी संपत्ति या विदेशी इनकम हो तो ITR-2 या ITR-3 चाहिए।",
  "it.w_director": "कंपनी का डायरेक्टर ITR-1 या ITR-4 इस्तेमाल नहीं कर सकता।",
  "it.w_unlisted": "अनलिस्टेड शेयर हों तो ITR-1 और ITR-4 नहीं चलते।",
  "it.w_agri": "₹5,000 से ऊपर खेती की इनकम पर ITR-1 और ITR-4 नहीं चलते।",
  "it.w_loss": "आगे ले जाने या सेट-ऑफ़ करने वाले नुकसान हों तो ITR-2 या ITR-3 चाहिए।",
  "it.w_esop": "एम्प्लॉयर के शेयरों पर टाला गया टैक्स हो तो ITR-2 या ITR-3 चाहिए।",
  "it.w_crypto": "वर्चुअल डिजिटल एसेट से इनकम हो तो ITR-2 या ITR-3 चाहिए।",
  "it.w_huf": "ITR-1 सिर्फ़ व्यक्तियों के लिए है; बिना बिज़नेस इनकम वाला HUF ITR-2 भरता है।",
  "it.w_pres2": "आपके दूसरे जवाबों से ITR-4 नहीं चलता, इसलिए बिज़नेस इनकम ITR-3 में जाती है।",
  "it.w_pres": "प्रिज़म्प्टिव बिज़नेस इनकम और साधारण दूसरी इनकम के लिए ITR-4 सही है।",
  "it.w_simple": "सिर्फ़ सैलरी, मकान और ब्याज, सीमाओं के अंदर, तो ITR-1 सही है।",
  "it.n_forms": "शर्तें 31 March 2026 को खत्म हुए साल के लिए जारी रिटर्न के अनुसार हैं (टैक्स पोर्टल के अनुसार ITR-1 और ITR-4 में अब दो तक मकान चलते हैं)। टैक्स साल 2026-27 के रिटर्न Income-tax Rules, 2026 के तहत अभी जारी होने हैं: भरने से पहले फ़ॉर्म में लिखी लिस्ट पढ़ें कि कौन उसे इस्तेमाल नहीं कर सकता।",
  "it.n_ltcg": "कुछ सालों में लिस्टेड शेयर या इक्विटी फ़ंड पर छोटे लॉन्ग-टर्म गेन ITR-1 और ITR-4 में चलते थे; 2026-27 के लिए यह पक्का नहीं है, इसलिए ITR-2 सुरक्षित है और फ़ॉर्म की अपनी लिस्ट ही आखिरी है।",
  "it.n_ae": "सेक्शन 44AE (माल ढुलाई वाहन) की अपनी शर्तें हैं; प्रिज़म्प्टिव फ़ॉर्म इस्तेमाल करने से पहले उन्हें जाँच लें।",
  "it.n_tax": "प्रिज़म्प्टिव रेट से कम मुनाफ़ा दिखाने के लिए किताबें चाहिए और ऑडिट भी लग सकता है: तब रिटर्न ITR-3 होता है।",
