  "nav.ca": "अकाउंटेंट व्यूअर",
  "ca.mk": "मेरे अकाउंटेंट के लिए फ़ाइल बनाएँ (सिर्फ़ पढ़ने के लिए)",
  "ca.t": "मेरे अकाउंटेंट के लिए फ़ाइल",
  "ca.intro": "एक बिज़नेस और अवधि को एक ही सिर्फ़-पढ़ने वाली फ़ाइल (.nsca) में पैक करता है। इसे WhatsApp या ईमेल से अपने अकाउंटेंट को भेजें। वे इसे ca.niveshsahayak.in पर खोलते हैं, किताबें पढ़ते हैं, सवाल जोड़ते हैं और कमेंट आपको वापस भेजते हैं।",
  "ca.notlive": "यह फ़ाइल सौंपना है, कोई लाइव शेयर्ड लॉगिन नहीं। आपका अकाउंटेंट किताबें वैसी ही देखता है जैसी फ़ाइल बनाते समय थीं। लाइव लॉगिन के लिए ऐसा सर्वर चाहिए जो आपकी किताबें रखे, और Nivesh Sahayak के पास कोई सर्वर नहीं: आपकी किताबें आपके डिवाइस पर रहती हैं। नई एंट्री के लिए नई फ़ाइल बनाएँ।",
  "ca.what": "इसमें क्या जाता है",
  "ca.earlier": "पहली तारीख से पहले की एंट्री भी (शुरुआती बैलेंस और एजिंग के लिए ज़रूरी)",
  "ca.items": "खरीद और बिक्री रेट वाली आइटम लिस्ट (स्टॉक के लिए ज़रूरी)",
  "ca.extra": "सिर्फ़ टिक करने पर",
  "ca.extrah": "टिक न करें तो छोड़ दिया जाता है। तस्वीरें (लोगो, साइन), आपका PIN और बैकअप सेटिंग कभी शामिल नहीं होते।",
  "ca.orders": "कोटेशन, प्रोफ़ॉर्मा इनवॉइस, सेल्स ऑर्डर, चालान और परचेज़ ऑर्डर",
  "ca.staff": "सैलरी स्लिप, स्टाफ़ एडवांस, लोन और EMI, पेटी कैश, और कर्मचारी लिस्ट",
