  "ca.codeh": "यह कोड अपने मैसेज में भेजें, या कॉल पर पढ़कर बताएँ। आपका अकाउंटेंट इसे फ़ाइल में दिखे कोड से मिलाता है, जिससे रास्ते में बदली फ़ाइल पकड़ी जाती है।",
