  "ca.cT": "CA के कमेंट",
  "ca.cIntro": "आपका अकाउंटेंट सवालों और कमेंट की एक छोटी फ़ाइल (.nsca-comments) वापस भेजता है। हर सवाल उसकी एंट्री के साथ देखने के लिए इसे यहाँ लोड करें। जवाब दें, बंद मार्क करें, और वापस भेजने के लिए फ़ाइल फिर सेव करें।",
