  "ca.party": "पार्टी",
  "ca.screen": "स्क्रीन",
  "ca.general": "सामान्य कमेंट",
  "cv.h1": "अकाउंटेंट व्यूअर: क्लाइंट की भेजी किताबों की फ़ाइल खोलें",
  "cv.intro": "आपका क्लाइंट किसी अवधि की अपनी किताबें एक फ़ाइल में पैक करके WhatsApp या ईमेल से आपको भेजता है। इसे यहाँ खोलें और पढ़ें: बकाया, पार्टियाँ, लेजर, डे बुक, GST का हिसाब, फ़ाइनल अकाउंट और हर डॉक्यूमेंट। खोजें और फ़िल्टर करें, किसी भी एंट्री पर सवाल पूछें, और अपने कमेंट एक छोटी फ़ाइल में वापस भेजें। मुफ़्त, बिना लॉगिन, और कुछ अपलोड नहीं होता: फ़ाइल आपके ब्राउज़र के अंदर ही पढ़ी जाती है।",
  "cv.drop": ".nsca फ़ाइल यहाँ छोड़ें",
  "cv.choose": "फ़ाइल चुनें",
  "cv.dropnote": "फ़ाइल इसी डिवाइस पर रहती है। यहाँ कुछ सेव नहीं होता और आप यहाँ से क्लाइंट की किताबें नहीं बदल सकते।",
  "cv.nav.home": "सारांश",
  "cv.docs": "डॉक्यूमेंट",
  "cv.day": "डे बुक",
  "cv.fin": "फ़ाइनल अकाउंट",
  "cv.gst": "GST का हिसाब",
  "cv.cT": "सवाल और कमेंट",
  "cv.how.h": "यह कैसे काम करता है",
  "cv.how.1": "आपका क्लाइंट Nivesh Sahayak खोलता है, मेरा डेटा में अपने अकाउंटेंट को भेजें पर जाता है, और एक बिज़नेस व अवधि के लिए \"मेरे अकाउंटेंट के लिए फ़ाइल बनाएँ\" चुनता है।",
  "cv.how.2": "वे आपको फ़ाइल (.nsca पर खत्म) और उसी मैसेज में एक छोटा चेक कोड भेजते हैं।",
  "cv.how.3": "आप इस पेज पर फ़ाइल खोलते हैं। पेज बताता है कि फ़ाइल बदली नहीं है, और क्लाइंट का दिया चेक कोड लिखकर मिलाने देता है।",
  "cv.how.4": "किताबें पढ़ें, खोजें, और किसी भी डॉक्यूमेंट, डे बुक एंट्री या स्क्रीन पर \"सवाल या कमेंट जोड़ें\" दबाएँ। आप जो भी लिखते हैं वह इसी ब्राउज़र में रहता है।",
  "cv.how.5": "काम पूरा होने पर \"सवाल और कमेंट\" खोलें और छोटी .nsca-comments फ़ाइल वापस भेजें। आपका क्लाइंट उसे लोड करता है और हर सवाल उसकी एंट्री के साथ देखता है। वे जवाब दे सकते हैं, और आप जवाब यहाँ लोड कर सकते हैं।",
  "cv.live.h": "फ़ाइल सौंपना, लाइव लॉगिन नहीं",
  "cv.live.p": "यह फ़ाइल सौंपना है। आप क्लाइंट के अकाउंट में लॉगिन नहीं करते और उनके बाद के बदलाव नहीं देखते। लाइव शेयर्ड लॉगिन के लिए ऐसा सर्वर चाहिए जो किताबें रखे, और Nivesh Sahayak के पास कोई सर्वर नहीं: किताबें क्लाइंट के डिवाइस पर रहती हैं। नई अवधि या सुधार के बाद क्लाइंट से नई फ़ाइल माँगें।",
  "cv.safe.h": "फ़ाइल में क्या है, और क्या नहीं",
  "cv.safe.p": "क्या जाएगा यह आपका क्लाइंट टिक करता है। आमतौर पर फ़ाइल में एक बिज़नेस की अवधि के आखिर तक की एंट्री, पार्टियाँ और आइटम होते हैं। कोटेशन और ऑर्डर, सैलरी और स्टाफ़ के रिकॉर्ड, फ़ोन नंबर और ईमेल पते, और बिज़नेस के बैंक खाते की जानकारी तभी जाती है जब क्लाइंट टिक करे। तस्वीरें, PIN और बैकअप सेटिंग कभी शामिल नहीं होते। फ़ाइल में चेकसम होता है, इसलिए कोई भी बदलाव इस पेज पर दिखता है। चेकसम उस व्यक्ति को नहीं रोक सकता जो फ़ाइल बदलकर उसे दोबारा निकाल ले, इसलिए चेक कोड को क्लाइंट के अलग से भेजे कोड से मिलाएँ।",
  "cv.readonly": "यह एक फ़ाइल का सिर्फ़-पढ़ने वाला व्यू है: यहाँ कुछ बदला या सेव नहीं किया जा सकता।",
  "cv.notfile": "यह Nivesh Sahayak की अकाउंटेंट फ़ाइल (.nsca) नहीं है।",
  "cv.iscomments": "यह कमेंट फ़ाइल है। पहले किताबों की फ़ाइल (.nsca) खोलें, फिर \"सवाल और कमेंट\" से कमेंट लोड करें।",
  "cv.newer": "यह फ़ाइल नए वर्ज़न से बनी है। पेज रीलोड करें और फिर कोशिश करें।",
  "cv.nostore": "आपके कमेंट इस ब्राउज़र में नहीं रखे जा सके। अभी कमेंट फ़ाइल सेव करें।",
