  "cp.unk_t": "{n} सप्लायर का साइज़ भरा नहीं",
  "cp.unk_p": "इन सप्लायर के बिल जाँचे नहीं जाते। इनमें कोई माइक्रो या छोटा उद्यम हो तो ऊपर उसका साइज़ भरें।",
  "cp.unk_l": "{n} बिल बाक़ी",
  "cp.disc": "यह पन्ना आपके डिवाइस पर आपके रिकॉर्ड से बना याद दिलाने वाला पन्ना है। यह क़ानूनी या टैक्स सलाह नहीं है। फ़ैसले से पहले सप्लायर का उद्यम सर्टिफ़िकेट देखें और CA से पूछें।",
  "cp.lim_p": "इस वित्त वर्ष और पिछले साल की आपकी अपनी बिक्री (टैक्स के बिना), उन सीमाओं के सामने जो कंपोज़िशन स्कीम, ई-इनवॉइस और ई-वे बिल तय करती हैं। सिर्फ़ ऐप में दर्ज इस बिज़नेस की बिक्री गिनी गई है। क़ानून एक PAN के सारे GSTIN और दूसरी तरह का टर्नओवर भी जोड़ता है, इसलिए CA से मिलान करें।",
