  "cp.l_ewb": "ई-वे बिल: माल की खेप {l} से ऊपर",
  "cp.rule_comp_goods": "पिछले वित्त वर्ष का टर्नओवर ₹1.5 करोड़ तक हो तो कंपोज़िशन स्कीम ली जा सकती है (अधिसूचना 14/2019-सेंट्रल टैक्स)। इससे ऊपर नहीं।",
  "cp.rule_comp_goods_sp": "आपका राज्य आठ पहाड़ी राज्यों में है, जहाँ सीमा ₹1.5 करोड़ की जगह ₹75 लाख है (अधिसूचना 14/2019-सेंट्रल टैक्स)।",
  "cp.rule_comp_serv": "पिछले साल ₹50 लाख तक टर्नओवर वाले सर्विस देने वाले कुल 6% टैक्स (3% सेंट्रल और 3% राज्य) दे सकते हैं (अधिसूचना 2/2019-सेंट्रल टैक्स (रेट))। वे बिल ऑफ़ सप्लाई देते हैं, टैक्स नहीं वसूल सकते, इनपुट क्रेडिट नहीं मिलता और दूसरे राज्य को सप्लाई नहीं कर सकते।",
  "cp.rule_einv": "कुल टर्नओवर ₹5 करोड़ से ऊपर हो तो ई-इनवॉइस ज़रूरी है (अधिसूचना 13/2020-सेंट्रल टैक्स, 10/2023 से बदली, 1 अगस्त 2023 से)। ठीक ₹5 करोड़ ऊपर नहीं गिना जाता। अधिसूचना पुराने सालों को भी देखती है: CA से पूछें।",
