  "cp.ewb_p": "माल की खेप की क़ीमत {l} से ऊपर हो तो ले जाने के लिए ई-वे बिल चाहिए (CGST नियम 138(1))। यह हर खेप पर देखा जाता है, साल पर नहीं। जिन बिलों की हर लाइन पर सर्विस कोड (SAC, 99 से शुरू) है वे नहीं गिने जाते; बिना कोड वाले बिल गिने जाते हैं, इन्हें जाँच लें।",
  "cp.ewb_n": "इस साल आपके {n} बिल उस क़ीमत से ऊपर हैं (सबसे बड़ा {m})। इन पर भेजे माल के लिए ई-वे बिल लग सकता है; सर्विस के लिए नहीं।",
