  "cp.special": "आपके बिज़नेस का राज्य उन पहाड़ी राज्यों में है जहाँ माल के लिए कंपोज़िशन की सीमा कम, ₹75 लाख, है: अरुणाचल प्रदेश, मणिपुर, मेघालय, मिज़ोरम, नागालैंड, सिक्किम, त्रिपुरा, उत्तराखंड।",
  "cp.rc_t": "1 जनवरी 2027 से: और सप्लाई पर ई-इनवॉइस",
  "cp.rc_p": "अधिसूचना 04/2026-सेंट्रल टैक्स (26 अक्टूबर 2026) 1 जनवरी 2027 से ई-इनवॉइस उन सप्लाई पर भी लाती है जिन पर ख़रीदार रिवर्स चार्ज में टैक्स देता है (जैसे बिना रजिस्ट्रेशन वाले सप्लायर से ख़रीद) और सर्विस के आयात पर, ₹5 करोड़ से ऊपर वालों के लिए। अधिसूचना का पाठ 17 नवंबर 2026 को पढ़ा गया; भरोसा करने से पहले अधिसूचना ज़रूर देखें।",
  "cp.lim_disc": "ये आपके अपने रिकॉर्ड से बने याद दिलाने वाले अंदाज़े हैं, सलाह नहीं। क़ानून का टर्नओवर यहाँ दर्ज बिक्री से ज़्यादा चीज़ें जोड़ता है। CA से पूछें।",
  "cp.si2027": "1 जनवरी 2027 से बिना रजिस्ट्रेशन वाले सप्लायर से रिवर्स चार्ज की ख़रीद के सेल्फ़ इनवॉइस पर, टर्नओवर ₹5 करोड़ से ऊपर हो तो, ई-इनवॉइस (IRN) भी लग सकता है (अधिसूचना 04/2026-सेंट्रल टैक्स)। अधिसूचना देखें। यह ऐप अभी सेल्फ़ इनवॉइस की ई-इनवॉइस फ़ाइल नहीं बना सकता।",
