  "cp.scope": "यह नियम उन माइक्रो और छोटे सप्लायर के लिए है जो माल देते समय उद्यम पर रजिस्टर्ड थे। जो सप्लायर सिर्फ़ ख़रीद-बेच (ट्रेडिंग) करता है, वह आता है या नहीं, यह अपने CA से पूछें।",
