  "sfd.tab": "साझा फ़ोल्डर",
  "sfd.p": "कई कंप्यूटरों पर एक ही साझा फ़ोल्डर इस्तेमाल करें। हर कोई अपने कंप्यूटर पर ऐप खोलता है और सब एक ही फ़ोल्डर में पढ़ते-लिखते हैं, जैसे Windows का शेयर्ड फ़ोल्डर या OneDrive फ़ोल्डर। एक कंप्यूटर पर बना बिल कुछ ही सेकंड में बाकी पर दिख जाता है। न सर्वर, न कोई खर्चा।",
